"""Check that the superseded draft report and the final report carry identical Q1-Q5 values."""
import sys

import yaml

d = yaml.safe_load(open(sys.argv[1]))["rederivation_report"]
f = yaml.safe_load(open(sys.argv[2]))["rederivation_report"]


def q1(r):
    t = r["Q1_koblitz_orders_and_admissibility"]
    return ([(x["n"], x["order"], x["factorization"], x["equals_4_times_odd_prime"], x["two_sylow_cyclic"], x["admissible"])
             for x in t["table"]], t["admissible_n"], t["n17_divisors"])


def q2(r):
    t = r["Q2_control_cell_orders"]
    return [(k, t[k]["order"], t[k]["factorization"], t[k]["largest_prime_factor"]) for k in ("ordinary_control_one", "ordinary_control_two")] + [t["generic_control"]["l"]]


def q3(r):
    return [(x["cell"], x["reading"], x["N"], x["e"], x["log2_M_unrounded"], x["M"],
             x.get("log2_M_unrounded_14sig", x.get("log2_M_unrounded_12dp"))) for x in r["Q3_alphabet_grid"]["rows"]]


def q4(r):
    t = r["Q4_repriced_sample_sizes"]
    return ([(x["cell"], x["reading"], x["e"], x["M"], x["log2_S_min"], x["log2_S_pow2"]) for x in t["rows"]],
            [(x["cell"], x["reading"], x["log2_sum_S_min"]) for x in t["per_cell_reading_sums"]["rows"]],
            [(x["alphabet"], x["log2_S_min"], x["log2_S_pow2"]) for x in t["composite_control_alphabets"]],
            t["composite_pair_sum_optional"]["log2_sum_S_min"])


def q5(r):
    return [(x["k"], x["ambient"], x["log2_L"], x["capacity_bits"], x["gap_bits"]) for x in r["Q5_ambient_gap_table"]["rows"]]


res = {name: fn(d) == fn(f) for name, fn in (("Q1", q1), ("Q2", q2), ("Q3", q3), ("Q4", q4), ("Q5", q5))}
print("draft vs final, Q-values identical per section:", res, "| all identical:", all(res.values()))

