"""Elementary primality certificates for every prime used in Q1, Q2, Q5 (no recalled
deterministic-MR bound is load-bearing).

Lucas's criterion (proved in one line): if a^(N-1) = 1 mod N and a^((N-1)/q) != 1 mod N for
every prime q | N-1, then a has order N-1 in (Z/N)^*, so phi(N) >= N-1 and N is prime.
Base case: trial division for N < 2^20. The factorisation of N-1 is FOUND with
sympy.factorint but VERIFIED here (product check + each factor recursively certified).
"""
import json
import sys

import sympy

BASE = 1 << 20
_cache = {}


def trial_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True


def certify(n):
    if n in _cache:
        return _cache[n]["ok"]
    if n < BASE:
        ok = trial_prime(n)
        _cache[n] = {"method": "trial division", "ok": ok}
        return ok
    fac = {int(p): int(e) for p, e in sympy.factorint(n - 1).items()}
    prod = 1
    for p, e in fac.items():
        prod *= p ** e
    if prod != n - 1:
        _cache[n] = {"ok": False, "why": "factorisation of n-1 does not multiply back"}
        return False
    subs_ok = all(certify(p) for p in fac)
    for a in range(2, 2000):
        if pow(a, n - 1, n) != 1:
            _cache[n] = {"ok": False, "why": f"Fermat witness {a}: composite"}
            return False
        if all(pow(a, (n - 1) // p, n) != 1 for p in fac):
            _cache[n] = {"method": "Lucas N-1", "a": a, "n_minus_1": {str(p): e for p, e in fac.items()},
                         "ok": subs_ok}
            return subs_ok
    _cache[n] = {"ok": False, "why": "no Lucas witness < 2000"}
    return False


def main():
    q = json.load(open("out_q1_q2.json"))
    primes = set()
    for r in q["q1"]:
        primes |= {int(p) for p in r["factorization_dict"]}
    for name in ("ordinary_control_one", "ordinary_control_two"):
        primes |= {int(p) for p in q["q2"][name]["factorization_dict"]}
    primes.add(q["q2"]["generic_control"]["l"])
    L_DEP = 680564733841876926932320129493409985129
    primes.add(L_DEP)
    results = {str(p): certify(p) for p in sorted(primes)}
    out = {"n_primes_certified": len(results), "all_certified": all(results.values()),
           "failures": [p for p, ok in results.items() if not ok],
           "certificates": {str(k): v for k, v in sorted(_cache.items())}}
    json.dump(out, sys.stdout, indent=1)
    print()


if __name__ == "__main__":
    main()

